--
-- Window Rules
--

-- wayland wine
hl.window_rule({
    match = { class = ".*\\.exe" },
    float = false,
    --size = "80% 80%",
    --decorate = false,
})

--
-- Key-Bindings
--

-- Sets "Windows" key as main modifier
local mainMod = "SUPER"

-- Programs
hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal)) -- Terminal
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(menu)) -- dmenu
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd("$fileManager")) -- dolphin
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_raw(screenshot)) -- grimshot / flameshot
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(editor)) -- Emacs

-- show cliphist
hl.bind("SUPER + V", hl.dsp.exec_cmd("cliphist list | wofi --show dmenu | cliphist decode | wl-copy"))

-- ssh interactive remote selection
hl.bind("SUPER + S", hl.dsp.exec_cmd("~/.local/bin/ssh-host-menu.zsh"))

-- WM Control
hl.bind(mainMod .. " + ALT + q", hl.dsp.exit()) -- Quit
hl.bind(mainMod .. " + W", hl.dsp.window.close()) -- Close Active Window
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.window.kill()) -- Kill Active Window
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })) -- Fullscreen Active Window

-- Navigation
hl.bind(mainMod .. " + h", hl.dsp.focus({ direction = "left" })) -- Move Focus: Left
hl.bind(mainMod .. " + l", hl.dsp.focus({ direction = "right" })) -- Move Focus: Right
hl.bind(mainMod .. " + j", hl.dsp.focus({ direction = "down" })) -- Move Focus: Down
hl.bind(mainMod .. " + k", hl.dsp.focus({ direction = "up" })) -- Move Focus: Up

hl.bind(mainMod .. " + SHIFT + h", hl.dsp.window.move({ direction = "l" })) -- Move Window: Left
hl.bind(mainMod .. " + SHIFT + l", hl.dsp.window.move({ direction = "r" })) -- Move Window: Right
hl.bind(mainMod .. " + SHIFT + j", hl.dsp.window.move({ direction = "d" })) -- Move Window: Down
hl.bind(mainMod .. " + SHIFT + k", hl.dsp.window.move({ direction = "u" })) -- Move Window: Up

hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag()) -- Move Window: LMB/RMB
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize()) -- Resize Window: LMB/RMB

-- Switch Workspace Focus
hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + 0", hl.dsp.focus({ workspace = 10 }))

-- Move Window to Workspace
hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.window.move({ workspace = 1, follow = false }))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.window.move({ workspace = 2, follow = false }))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.window.move({ workspace = 3, follow = false }))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.window.move({ workspace = 4, follow = false }))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.window.move({ workspace = 5, follow = false }))
hl.bind(mainMod .. " + SHIFT + 6", hl.dsp.window.move({ workspace = 6, follow = false }))
hl.bind(mainMod .. " + SHIFT + 7", hl.dsp.window.move({ workspace = 7, follow = false }))
hl.bind(mainMod .. " + SHIFT + 8", hl.dsp.window.move({ workspace = 8, follow = false }))
hl.bind(mainMod .. " + SHIFT + 9", hl.dsp.window.move({ workspace = 9, follow = false }))
hl.bind(mainMod .. " + SHIFT + 0", hl.dsp.window.move({ workspace = 10, follow = false }))

-- Audio
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ +2%"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ -2%"))
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("pactl set-sink-mute @DEFAULT_SINK@ toggle"))
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"))
