--
-- Autostart
--
hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("anytype") -- doppelt weil der zuerst in background geht
    hl.exec_cmd("anytype", { workspace = "1 silent" })
    hl.exec_cmd("dbus-launch firefox", { workspace = "2 silent" })
    hl.exec_cmd("~/.local/bin/tor-browser", { workspace = "4 silent" })
    hl.exec_cmd("emacs", { workspace = "4 silent" })
    hl.exec_cmd("dbus-launch waybar") -- Launch: waybar
    hl.exec_cmd("dbus-launch hyprpaper") -- Launch: hyprpaper
    hl.exec_cmd("dbus-launch dunst") -- Launch: dunst
    --hl.exec_cmd("hypridle") -- Launch: hypridle
    hl.exec_cmd("dbus-launch foot --server &") -- Launch: foot --server
    hl.exec_cmd("ssh-agent -a $XDG_RUNTIME_DIR/ssh-agent.sock")  -- Launch: ssh-agent
    -- Launch: pipewire
    hl.exec_cmd("dbus-launch pipewire")
    hl.exec_cmd("dbus-launch pipewire-pulse")
    hl.exec_cmd("dbus-launch wireplumber")
    -- Launch: cliphist
    hl.exec_cmd("wl-paste --type text --watch cliphist store &")
    hl.exec_cmd("wl-paste --type image --watch cliphist store &")
end)
